def get_opener(self, *args):
        """
        If ssl module is available, will return secure (verified HTTPS) opener
        Elif --allow-no-ssl, then standard opener
        Else fail
        """
        if ssl:
            https_handler = VerifiedHTTPSHandler()
            return urllib2.build_opener(https_handler, *args)
        elif os.environ.get('PIP_ALLOW_NO_SSL', '') == '1':
            return urllib2.build_opener(*args)
        else:
            raise_no_ssl_exception()

def get_opener(self, *args, **kwargs):
        """
        Build an OpenerDirector instance based on the scheme, whether ssl is
        importable and the --allow-no-ssl parameter.
        """
        if kwargs.get('scheme') == 'https':
            if ssl:
                https_handler = VerifiedHTTPSHandler()
                return urllib2.build_opener(https_handler, *args)
            if not ssl and os.environ.get('PIP_ALLOW_NO_SSL', '') == '1':
                return urllib2.build_opener(*args)
            else:
                raise_no_ssl_exception()
        else:
            return urllib2.build_opener(*args)

def tuplize_dict(data_dict: dict[str, Any]) -> FlattenDataDict:
    '''Takes a dict with keys of the form 'table__0__key' and converts them
    to a tuple like ('table', 0, 'key').

    Dict should be put through parse_dict before this function, to have
    values standardized.

    May raise a DataError if the format of the key is incorrect.
    '''
    tuplized_dict: FlattenDataDict = {}
    for k, value in data_dict.items():
        key_list = cast("list[Union[str, int]]", k.split('__'))
        for num, key in enumerate(key_list):
            if num % 2 == 1:
                try:
                    key_list[num] = int(key)
                except ValueError:
                    raise df.DataError('Bad key')
        tuplized_dict[tuple(key_list)] = value
    return tuplized_dict

def _read_from_sections(user, collection_url, permission):
    """Get regex sections."""
    filename = os.path.expanduser(config.get("rights", "file"))
    rights_type = config.get("rights", "type").lower()
    regex = ConfigParser({"login": user, "path": collection_url})
    if rights_type in DEFINED_RIGHTS:
        log.LOGGER.debug("Rights type '%s'" % rights_type)
        regex.readfp(StringIO(DEFINED_RIGHTS[rights_type]))
    elif rights_type == "from_file":
        log.LOGGER.debug("Reading rights from file %s" % filename)
        if not regex.read(filename):
            log.LOGGER.error("File '%s' not found for rights" % filename)
            return False
    else:
        log.LOGGER.error("Unknown rights type '%s'" % rights_type)
        return False

    for section in regex.sections():
        re_user = regex.get(section, "user")
        re_collection = regex.get(section, "collection")
        log.LOGGER.debug(
            "Test if '%s:%s' matches against '%s:%s' from section '%s'" % (
                user, collection_url, re_user, re_collection, section))
        user_match = re.match(re_user, user)
        if user_match:
            re_collection = re_collection.format(*user_match.groups())
            if re.match(re_collection, collection_url):
                log.LOGGER.debug("Section '%s' matches" % section)
                if permission in regex.get(section, "permission"):
                    return True
            else:
                log.LOGGER.debug("Section '%s' does not match" % section)
    return False

def ocr_to_dict(url):
    req = requests.get(url)
    text = req.content

    parser = lxml.etree.XMLParser(ns_clean=True,
                                  recover=True,
                                  encoding='utf-8')

    xml = lxml.etree.fromstring(text, parser=parser)

    parsed_text = {}

    for item in xml.iter():
        if not item.text:
            continue

        item.text = item.text.replace('&', '&amp;')
        item.text = item.text.replace('>', '&gt;')
        item.text = item.text.replace('<', '&lt;')

        if item.tag == 'title':
            if "title" not in parsed_text:
                parsed_text["title"] = []
            parsed_text["title"].append(item.text)
        else:
            txt = " ".join([i for i in item.text.split()[:10] if not i.isupper()])
            if len(item.text.split()) > 10:
                for i in item.text.split()[10:]:
                    txt += " " + i
            if "p" not in parsed_text:
                parsed_text["p"] = []
            parsed_text["p"].append(txt)

    for part in parsed_text:
        parsed_text[part] = "".join(parsed_text[part])

    return parsed_text

